import{_ as r,a0 as a,w as l,s as i,ao as m,I as s,x as e,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在終端下截取一個完整長度的網頁截圖 | LCTT x X-CMD","titleTemplate":false,"description":"如何在終端下截取一個完整長度的網頁截圖 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在終端下截取一個完整長度的網頁截圖 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在終端下截取一個完整長度的網頁截圖 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/How to take full length screenshots of websites via terminal","title":"如何在終端下截取一個完整長度的網頁截圖","tag":"201406","desc":""},"relativePath":"201406/How to take full length screenshots of websites via terminal.md","filePath":"[post].md"}'),d={name:"201406/How to take full length screenshots of websites via terminal.md"};function u(g,t,w,h,f,T){const o=a("Link");return l(),i("div",null,[t[11]||(t[11]=m(`<h1 id="如何在終端下截取一個完整長度的網頁截圖" tabindex="-1">如何在終端下截取一個完整長度的網頁截圖 <a class="header-anchor" href="#如何在終端下截取一個完整長度的網頁截圖" aria-label="Permalink to “如何在終端下截取一個完整長度的網頁截圖”">​</a></h1><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Screenshot-790x526.png" alt=""></p><p>與其記筆記或是把看到的內容發送給其他人，我們更經常通過截屏來幫助我們記憶。 但是通常情況下，如果一個網頁超出了屏幕高度，我們就得用多張截圖去截取其全部內容。</p><p>對於 Linux，你將會有一個更好的解決方案：使用一個 GNOME 的應用來截取某個鏈接的整個頁面。 這個應用叫做 <strong>gnome-web-photo</strong>，這篇文章將介紹如何安裝和使用它。</p><p>在 Ubuntu 和 Debian 的分支下：</p><pre><code>$ sudo apt-get install gnome-web-photo
</code></pre><p>在 Fedora 下：</p><pre><code>$ sudo yum install gnome-web-photo
</code></pre><p>但是對於 CentOS 和其他 RedHat 分支的用户，請注意 <code>gnome-web-photo</code> 依賴 GTK+ 3.0 這個軟件包。 也就是説 <code>gnome-web-photo</code> 是和 <strong>CentOS/RHEL 6 自帶的 GNOME 2 不相兼容的</strong>。</p><p>要為一個網頁截圖：</p><pre><code>$ gnome-web-photo -t 0 --mode=photo http://www.unixmen.com output.png
</code></pre><p>上面這條命令將為 Unixmen 的主頁截取一個完整長度的截圖，並保存在當前工作目錄下。</p><p>輸出樣例：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/output2.png" alt=""></p><p><strong>-t</strong> 這個參數可以設置生成截圖的超時時間。<strong>-t 0</strong> 則表示禁用超時參數。</p><p><strong>通過</strong> gnome-web-photo，你可以用下面的命令為一個網頁生成一個縮略圖：（默認大小是 <strong>256×256</strong>，但是可以通過 “<strong>-s</strong>” 來指定縮略圖的大小）</p><pre><code>$ gnome-web-photo -t 0 -s 128 --mode=thumbnail http://www.unixmen.com output.png
</code></pre><p>輸出樣例：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/output.png" alt=""></p><p>如果你想將網頁截取成一個可供打印的多頁 PDF 文檔，你可以輸入下面的命令：</p><pre><code>$ gnome-web-photo -t 0 --mode=print http://www.unixmen.com output.pdf
</code></pre><p>注意這個應用並不支持 <strong>.jpg</strong> 格式。</p><p>這個應用應該對各類用户都有所幫助。我經常對網頁進行縮略圖和完整長度的截圖，希望對你也有所幫助。</p><hr>`,24)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://www.unixmen.com/take-full-length-screenshots-websites-via-terminal/"},{default:p(()=>[...t[0]||(t[0]=[e("http://www.unixmen.com/take-full-length-screenshots-websites-via-terminal/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(o,{href:"https://github.com/vizv"},{default:p(()=>[...t[2]||(t[2]=[e("VizV",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const C=r(d,[["render",u]]);export{x as __pageData,C as default};
